Definition art_enq_new_fp (sp t spb ris qs km b L B : Z) (x : Z) : Prop :=
  (sp - 64 <= x < sp) \/ art_refill_fp (sp - 64) t spb ris qs 24 km x \/ (t + 208 + 2576 <= x < t + 208 + 2584)
  \/ (b <= x < b + 32) \/ (L <> 0 /\ B <= x < B + 8) \/ (t + 80 <= x < t + 112 /\ (L <> 0 -> ~ (t + 88 <= x < t + 96))).
